(() => {
'use strict';
const $=s=>document.querySelector(s),c=window.HVT,api=window.HVTSections,rich=window.HVTRich;
let resource=null,rows=[],publicRows=[],current=null,dirty=false,busy=false,loadToken=0,preview=false;
const host=$('#sectionWorkspace'),form=$('#sectionForm');
const editor=rich.mount($('#sectionRich'),{label:'Nội dung trang hoặc Chương Phẩm',onChange:()=>setDirty(true)});
function say(text,error=false){$('#sectionStatus').textContent=text;$('#sectionStatus').classList.toggle('error',error)}
function setDirty(value){dirty=value;$('#sectionDirty').textContent=value?'Có thay đổi chưa lưu':'Chưa có thay đổi mới'}
function controls(value){busy=value;$('#sectionFields').disabled=value;editor.setDisabled(value);host.querySelectorAll('[data-section-action],#newSection,#reloadSections').forEach(b=>b.disabled=value);$('#saveSection').disabled=value||preview||!resource;$('#publishSection').disabled=value||preview||!resource}
function confirmLeave(){return !dirty||confirm('Phần đang soạn có thay đổi chưa lưu. Bạn muốn rời đi và bỏ các thay đổi này?')}
function heading(row){return row.label?row.label+' '+row.number+(row.title?' — '+row.title:''):(row.title||'Trang '+row.number)}
function status(row){const live=publicRows.find(p=>p.id===row.id);return !live?'Bản nháp':live.source_version===row.version?'Đã công khai':'Có bản sửa chưa công khai'}
function renderList(){ $('#sectionList').innerHTML=rows.length?rows.map(row=>`<div class="section-row"><div><strong>${c.esc(heading(row))}</strong><small>${status(row)}</small></div><div><button type="button" class="text-link" data-section-action="edit" data-id="${row.id}">Viết tiếp</button>${publicRows.some(p=>p.id===row.id)?`<button type="button" class="text-link" data-section-action="unpublish" data-id="${row.id}">Ẩn</button>`:''}<button type="button" class="text-link section-delete" data-section-action="delete" data-id="${row.id}">Xóa</button></div></div>`).join(''):'<p class="hint">Chưa có trang hoặc Chương/Phẩm. Bắt đầu phần đầu tiên bên dưới.</p>';$('#sectionCount').textContent=rows.length+' phần đã lưu · '+publicRows.length+' phần công khai';controls(busy)}
function newDraft(){current=null;form.reset();form.elements.number.value=Math.max(0,...rows.map(r=>r.number))+1;if(rows.length)form.elements.label.value=rows.at(-1).label;editor.setHTML('');setDirty(false);$('#sectionEditTitle').textContent='Viết trang / phần mới';say(resource?'Lưu nháp để viết tiếp sau, hoặc lưu và công khai ngay.':'Lưu thông tin bộ Kinh/Sách ở trên trước khi lưu trang/phần.');controls(false)}
async function fetchRows(){const token=++loadToken;const target=resource?.id;if(!target){rows=[];publicRows=[];renderList();return}const result=await Promise.all([api.drafts(target),api.publicSections(target)]);if(token!==loadToken||resource?.id!==target)return;[rows,publicRows]=result;renderList()}
function open(row){current={...row};form.elements.label.value=row.label;form.elements.number.value=row.number;form.elements.title.value=row.title;form.elements.rights.checked=false;editor.setHTML(row.body_html);$('#sectionEditTitle').textContent='Viết tiếp '+heading(row);setDirty(false);say('Đã tải bản lưu lúc '+new Date(row.updated_at).toLocaleString('vi-VN')+'. '+status(row)+'.');editor.focus()}
async function save(publish){if(preview||!resource||busy)return;const f=new FormData(form),number=Number(f.get('number'));if(!Number.isInteger(number)||number<1||number>99999){say('Thứ tự trang/phần phải từ 1 đến 99999.',true);return}if(publish&&!f.has('rights')){say('Vui lòng xác nhận đã kiểm tra nội dung và quyền chia sẻ trước khi công khai.',true);return}if(publish&&!editor.getText()){say('Vui lòng nhập nội dung trước khi công khai.',true);return}controls(true);let saved=null;try{const duplicate=rows.find(r=>r.label===f.get('label')&&r.number===number&&r.id!==current?.id);if(duplicate)throw Error('Đã có '+heading(duplicate)+'. Chọn “Viết tiếp” để sửa phần đó, hoặc dùng số khác.');saved=await api.save({id:current?.id||crypto.randomUUID(),resource_id:resource.id,label:f.get('label'),number,title:f.get('title').trim(),body_html:editor.getHTML(),version:current?.version||0});current=saved;setDirty(false);$('#sectionEditTitle').textContent='Viết tiếp '+heading(saved);if(publish)await api.publish(saved);await fetchRows();say(publish?'Đã công khai '+heading(saved)+'. Các phần khác được giữ nguyên.':'Đã lưu nháp '+heading(saved)+'. Bạn có thể đóng trang và quay lại viết tiếp. Người xem vẫn đọc bản công khai trước đó nếu có.')}catch(error){say((saved?'Đã lưu bản nháp; chưa xác nhận công khai hoặc tải lại danh sách. ':'')+(error.message.includes('does not exist')||error.message.includes('schema cache')?'Cần chạy supabase/upgrade-chapters.sql trước khi dùng Chương/Phẩm.':error.message),true)}finally{controls(false)}}
$('#saveSection').onclick=()=>save(false);form.onsubmit=e=>{e.preventDefault();save(true)};form.addEventListener('input',e=>{if(e.target.name!=='rights')setDirty(true)});
$('#newSection').onclick=()=>{if(confirmLeave())newDraft()};$('#reloadSections').onclick=async()=>{if(!confirmLeave())return;try{controls(true);await fetchRows();const row=rows.find(r=>r.id===current?.id);if(row)open(row);else newDraft()}catch(e){say(e.message,true)}finally{controls(false)}};
$('#sectionList').onclick=async e=>{const b=e.target.closest('[data-section-action]');if(!b||busy)return;const row=rows.find(r=>r.id===b.dataset.id);if(!row)return;if(b.dataset.sectionAction==='edit'){if(confirmLeave())open(row);return}if(!confirmLeave())return;const remove=b.dataset.sectionAction==='delete';if(!confirm(remove?'Xóa vĩnh viễn '+heading(row)+' và bản công khai đi kèm?':'Ẩn '+heading(row)+' khỏi trang đọc? Bản nháp vẫn được giữ.'))return;controls(true);try{const result=await(remove?api.remove(row.id):api.unpublish(row.id));if(!result?.length)throw Error('Không có thay đổi. Hãy tải lại danh sách và kiểm tra quyền quản trị.');await fetchRows();if(current?.id===row.id)newDraft();say(remove?'Đã xóa phần được chọn. Các phần khác vẫn được giữ nguyên.':'Đã ẩn phần được chọn; bạn vẫn có thể viết tiếp và công khai lại.')}catch(error){say(error.message,true)}finally{controls(false)}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
window.HVTChapterAdmin={canLeave:confirmLeave,hasDirty:()=>dirty,
 async attach(item,isPreview=false){const changed=resource?.id!==item?.id;resource=item;preview=isPreview;host.hidden=false;if(changed){loadToken++;rows=[];publicRows=[];newDraft();renderList()}$('#sectionParentTitle').textContent=item?.title||'Trang / phần của bộ Kinh/Sách mới';if(item&&!preview){try{await fetchRows();if(changed&&!current&&!dirty)newDraft()}catch(e){say('Chưa tải được Chương/Phẩm. Kiểm tra kết nối hoặc chạy supabase/upgrade-chapters.sql. '+e.message,true)}}else{renderList();newDraft()}},
 detach(){loadToken++;resource=null;rows=[];publicRows=[];current=null;setDirty(false);host.hidden=true;editor.setHTML('')},
 setBusy:controls};
})();
